<template>
    <div class="smart-classroom-page">
    <aside class="control-panel">
      <div class="panel-title">三维模拟教室</div>

      <div class="group">
        <div class="group-title">场景</div>
        <div class="btn-row">
          <button class="btn btn-blue" @click="reloadScene">重载场景</button>
          <button class="btn btn-green" @click="loadModels" :disabled="loadingModel">加载 {{ modelStatusHint }} 模型</button>
          <button class="btn btn-purple" @click="focusRobot" :disabled="!robotLoaded">定位机器人</button>
        </div>
      </div>

      <div class="group">
        <div class="group-title">起点 / 终点放置</div>
        <p class="tip">点击地面放置坐标，当前模式：{{ placementLabel }}</p>
        <div class="btn-row">
        <button class="btn btn-blue" @click="setPlacementMode('start')">标记起点</button>
          <button class="btn btn-blue" @click="setPlacementMode('end')">标记终点</button>
          <button class="btn btn-green" @click="clearPoints">清空点位</button>
        </div>
      </div>

      <div class="group">
        <div class="group-title">障碍物（矩形）</div>
        <div class="btn-row">
          <button
            class="btn btn-orange"
            :class="{ active: drawingMode }"
            @click="toggleDrawObstacleMode"
          >
            {{ drawingMode ? '退出绘制' : '拖拽绘制障碍' }}
          </button>
          <button class="btn btn-orange" @click="undoObstacle">撤销</button>
          <button class="btn btn-orange" @click="clearAllObstacles">清空障碍</button>
        </div>
        <div class="btn-row">
          <button class="btn btn-olive" @click="saveObstacles">保存障碍数据</button>
          <button class="btn btn-olive" @click="triggerObstacleImport">导入障碍数据</button>
          <button class="btn btn-olive" @click="exportObstacles">导出障碍数据</button>
          <input
            ref="obstacleFileInputRef"
            type="file"
            accept="application/json"
            @change="importObstacles"
            style="display:none"
          />
        </div>
      </div>

      <div class="group">
        <div class="group-title">课堂巡视路径</div>
        <div class="btn-row">
          <button class="btn btn-purple" @click="planPath" :disabled="!canPlan">A* 自动规划</button>
          <button class="btn btn-purple" @click="walkPath" :disabled="!canWalk">一键驱动</button>
          <button class="btn btn-purple" @click="focusRobot" :disabled="!robotLoaded">快速定位机器人</button>
        </div>
        <div class="btn-row">
          <button class="btn btn-green" @click="saveCurrentRoute" :disabled="!currentPath.length">保存当前路线</button>
          <button class="btn btn-blue" @click="clearCurrentPath">清空当前路线</button>
          <button class="btn btn-red" @click="stopWalk">停止移动</button>
        </div>
      </div>

      <div class="group">
        <div class="group-title">路线管理</div>
        <div v-if="routes.length === 0" class="empty-tip">暂无保存路线</div>
        <div v-else class="route-list">
          <div
            v-for="route in routes"
            :key="route.id"
            class="route-item"
          >
            <button class="btn btn-blue route-name" @click="loadRoute(route)">{{ route.name }}</button>
            <button class="btn btn-green" @click="runSavedRoute(route)">运行</button>
            <button class="btn btn-red" @click="deleteRoute(route.id)">删除</button>
          </div>
        </div>
      </div>

      <div class="group">
        <div class="group-title">地面拾取</div>
        <div class="tip">射线拾取会实时显示当前点击点坐标；单位：米（米制）</div>
        <div class="tip" v-if="hoverPointText">当前坐标：{{ hoverPointText }}</div>
      </div>

      <div class="status-line">
        <span>障碍物：{{ obstacles.length }}</span>
        <span>已保存路线：{{ routes.length }}</span>
        <span>当前路径点：{{ currentPath.length }}</span>
      </div>
    </aside>

    <div class="scene-container">
      <div ref="sceneContainer" class="three-scene" aria-label="Three.js 三维模拟教室"></div>
    </div>

    <div class="status-bar">{{ statusText }}</div>
  </div>
</template>

<script setup>
import { onUnmounted, onMounted, ref, computed, shallowRef, markRaw } from 'vue';
import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader.js';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { PathPlanner } from '@/utils/PathPlanner';
import axios from 'axios';

const PUBLIC_ASSET_BASE = process.env.BASE_URL || '/';
const BASE_WITH_TRAILING_SLASH = PUBLIC_ASSET_BASE.endsWith('/') ? PUBLIC_ASSET_BASE : `${PUBLIC_ASSET_BASE}/`;
const SMART_CLASSROOM_SCENE_FOLDER = `${BASE_WITH_TRAILING_SLASH}japanese-classroom`;
const SCENE_DIRECTORY_PATH = SMART_CLASSROOM_SCENE_FOLDER;
const ROBOT_DIRECTORY_PATH = `${BASE_WITH_TRAILING_SLASH}models`;
const modelStatusHint = `场景目录：${SCENE_DIRECTORY_PATH} | 机器人目录：${ROBOT_DIRECTORY_PATH}`;

const sceneContainer = ref(null);
const obstacleFileInputRef = ref(null);
const statusText = ref(`请先在左侧加载 ${modelStatusHint} 下的场景与机器人资源`);
const hoverPointText = ref('');
const loadingModel = ref(false);
const robotLoaded = ref(false);
const modelLoadError = ref('');
const scene = shallowRef(null);
const camera = shallowRef(null);
const renderer = shallowRef(null);
const controls = shallowRef(null);
const raycaster = shallowRef(markRaw(new THREE.Raycaster()));
const pointer = shallowRef(markRaw(new THREE.Vector2()));
const hoverPoint = shallowRef(markRaw(new THREE.Vector2()));
const clock = shallowRef(markRaw(new THREE.Clock()));
const animationId = ref(0);

const groundMesh = shallowRef(null);
const robotGroup = shallowRef(null);
const robotModel = shallowRef(null);
const robotGroups = shallowRef([]);
const startMarker = shallowRef(null);
const endMarker = shallowRef(null);
const pathLine = shallowRef(null);
const gridHelper = shallowRef(null);

const obstacles = ref([]);
const obstacleMeshes = shallowRef([]);
const defaultObstacleMeshes = shallowRef([]);
const obstaclesByRect = ref([]);
const routes = ref([]);
const placementMode = ref('start');
const drawingMode = ref(false);
const isDrawing = ref(false);
const drawStart = ref(null);
const drawPreview = ref(null);

const startPoint = ref(null);
const endPoint = ref(null);
const currentPath = ref([]);

const isWalking = ref(false);
const walkIndex = ref(0);

const OBSTACLE_KEY = 'smart-classroom-obstacles-v2';
const ROUTE_KEY = 'smart-classroom-routes-v2';
const DEFAULT_WALK_ANIMATION_KEYWORDS = ['walking', 'walk', 'walk_0', '步', '步行'];
const ROBOT_DISPLAY_SCALE = 0.6;
const MODEL_FILE_EXTENSIONS = ['.fbx', '.FBX', '.gltf', '.GLTF', '.glb', '.GLB'];
const MODEL_FILES = [
  `${SCENE_DIRECTORY_PATH}/scene.gltf`,
  `${ROBOT_DIRECTORY_PATH}/Walking.fbx`
];

const dedupeModelFiles = (files) => {
  const normalized = files
    .filter((item) => typeof item === 'string')
    .map((item) => item.trim())
    .filter(Boolean);

  return [...new Set(normalized)];
};
const ROBOT_GROUP_OFFSET_X = 40;
const SCENE_MODEL_OFFSET_X = 320;
const SCENE_SCALE = {
  default: 1
};
const MODEL_SCALE = {
  default: 1,
  robot: 0.06,
  scene: 0.2
};

const modelGroups = [];
const modelGroupIndex = {};
const robotMixers = shallowRef([]);
const robotActions = shallowRef([]);
const robotAnimationData = shallowRef(null);

const getModelFileName = (url) => {
  const rawName = url.split('/').pop();
  return decodeURIComponent(rawName || '');
};

const placementLabel = computed(() => {
  return placementMode.value === 'start' ? '点击放置起点' : '点击放置终点';
});

const isRobotModelFile = (url) => {
  const name = getModelFileName(url).toLowerCase();
  return name.includes('walking') || name.includes('人形机器人') || name.includes('clasroom') || name.includes('巡检场景');
};

const isWalkAnimationFile = (url) => {
  const fileName = getModelFileName(url).toLowerCase();
  return DEFAULT_WALK_ANIMATION_KEYWORDS.some((keyword) => fileName.includes(keyword));
};

const isSceneModelFile = (url) => {
  const fileName = getModelFileName(url);
  return fileName.includes('japanese_classroom') || fileName.includes('japanese-classroom') || fileName.includes('scene.bin') || fileName.includes('scene.gltf');
};

const pickWalkClip = (asset) => {
  if (!asset || !Array.isArray(asset.animations) || !asset.animations.length) return null;
  return asset.animations.find((clip) => /walk/i.test(clip.name)) || asset.animations[0];
};

const makeClipInPlace = (sourceClip) => {
  if (!sourceClip) return null;
  const clip = sourceClip.clone();
  // Walking.fbx 的 mixamorigHips.position 含有根位移。完全移除位置轨道，
  // 让外层 Group 独占 A* 位移，避免动画第一帧导致 Z 轴瞬移。
  clip.tracks = clip.tracks.filter((track) =>
    !(track.name.endsWith('.position') && /(hips|root)/i.test(track.name))
  );
  clip.resetDuration();
  return clip;
};

const bindWalkAnimationToRobotGroups = () => {
  const clip = robotAnimationData.value?.clip;
  if (!clip) return;

  robotActions.value = robotMixers.value.map((mixer) => {
    if (!mixer) return null;

    const action = mixer.clipAction(clip);
    action.enabled = false;
    return action;
  });
};

const playRobotWalkAction = () => {
  robotActions.value.forEach((action) => {
    if (!action) return;
    action.reset();
    action.setLoop(THREE.LoopRepeat);
    action.clampWhenFinished = false;
    action.timeScale = 1;
    action.enabled = true;
    action.play();
  });
};

const stopRobotWalkAction = () => {
  robotActions.value.forEach((action) => {
    if (!action) return;
    action.stop();
  });
};

const canPlan = computed(() => !!(endPoint.value && (robotGroup.value || startPoint.value)));

const canWalk = computed(() => currentPath.value.length >= 2);

const statusHintByMode = computed(() => {
    if (modelLoadError.value) return modelLoadError.value;
    if (drawingMode.value) return '障碍绘制模式：按下左键到抬起可创建一个轴向矩形';
    if (isWalking.value) return '机器人巡检中...';
    return placementLabel.value;
  });

const toLocalStorage = (key, value) => {
  try {
    localStorage.setItem(key, JSON.stringify(value));
  } catch (error) {
    console.error('写入本地存储失败：', error);
  }
};

const fromLocalStorage = (key) => {
  try {
    const raw = localStorage.getItem(key);
    return raw ? JSON.parse(raw) : null;
  } catch (error) {
    console.error('读取本地存储失败：', error);
    return null;
  }
};

let currentAnimationSpeed = 0.3;
let robotCurrentSpeed = 0;
const ROBOT_ACCELERATION = 8;
let robotYOffset = 0;
let sceneSessionId = 0;

function bumpSceneSession() {
  sceneSessionId += 1;
  return sceneSessionId;
}

function isCurrentSceneSession(sessionId) {
  return sessionId === sceneSessionId;
}

function safeAddToScene(object, sessionId) {
  if (!object) return false;
  if (!isCurrentSceneSession(sessionId) || !scene.value) return false;
  scene.value.add(object);
  return true;
}

function initScene() {
  if (!sceneContainer.value) {
    return;
  }

  const sessionId = bumpSceneSession();

  const width = sceneContainer.value.clientWidth;
  const height = sceneContainer.value.clientHeight;

  scene.value = markRaw(new THREE.Scene());
  scene.value.background = new THREE.Color(0x1a1f2a);

  camera.value = new THREE.PerspectiveCamera(45, width / height, 0.1, 5000);
  camera.value.position.set(0, 18, 35);

  renderer.value = new THREE.WebGLRenderer({ antialias: true, alpha: false });
  renderer.value.setSize(width, height);
  renderer.value.setPixelRatio(Math.min(devicePixelRatio, 2));
  sceneContainer.value.appendChild(renderer.value.domElement);

  controls.value = new OrbitControls(camera.value, renderer.value.domElement);
  controls.value.enableDamping = true;
  controls.value.dampingFactor = 0.1;
  controls.value.target.set(0, 8, 0);
  controls.value.minDistance = 6;
  controls.value.maxDistance = 52;
  controls.value.minPolarAngle = Math.PI * 0.12;
  controls.value.maxPolarAngle = Math.PI * 0.49;
  controls.value.addEventListener('change', clampCameraToClassroom);

  scene.value.add(new THREE.AmbientLight(0xffffff, 0.6));
  const directional = new THREE.DirectionalLight(0xffffff, 1);
  directional.position.set(200, 300, 120);
  directional.castShadow = true;
  scene.value.add(directional);

  const plane = new THREE.Mesh(
    new THREE.PlaneGeometry(1000, 1000),
    new THREE.MeshStandardMaterial({
      color: 0x202839,
      metalness: 0.1,
      roughness: 0.9,
      side: THREE.DoubleSide
    })
  );
  plane.rotation.x = -Math.PI / 2;
  plane.receiveShadow = true;
  plane.name = 'ground';
  scene.value.add(plane);
  groundMesh.value = plane;

  gridHelper.value = new THREE.GridHelper(1000, 100, 0x4b5d77, 0x2a3a50);
  scene.value.add(gridHelper.value);

  const axes = new THREE.AxesHelper(120);
  scene.value.add(axes);

  createMarker('start');
  createMarker('end');

  if (loadingModel.value) {
    return;
  }
  statusText.value = '场景已重置，当前可绘制障碍与放置点位';
  if (!loadingModel.value) {
    loadModels();
  }

  bindEvents();
  clock.value = new THREE.Clock();

  animate(sessionId);
}

function fitSceneModel(modelRoot) {
  modelRoot.updateMatrixWorld(true);
  const box = new THREE.Box3().setFromObject(modelRoot);
  const size = box.getSize(new THREE.Vector3());
  const maxDimension = Math.max(size.x, size.y, size.z);
  if (!Number.isFinite(maxDimension) || maxDimension <= 0) return;

  const scale = 145 / maxDimension;
  modelRoot.scale.setScalar(scale);
  modelRoot.updateMatrixWorld(true);

  const scaledBox = new THREE.Box3().setFromObject(modelRoot);
  const center = scaledBox.getCenter(new THREE.Vector3());
  modelRoot.position.x -= center.x;
  modelRoot.position.z -= center.z;
  modelRoot.position.y -= scaledBox.min.y;
  modelRoot.updateMatrixWorld(true);
  return new THREE.Box3().setFromObject(modelRoot);
}

function fitRobotModel(modelRoot) {
  modelRoot.scale.setScalar(1);
  modelRoot.updateMatrixWorld(true);
  let sourceBox = new THREE.Box3().setFromObject(modelRoot);
  let sourceSize = sourceBox.getSize(new THREE.Vector3());

  // 某些 FBX 使用 Z-up 或 X-up 坐标系，加载后会侧躺；根据最长轴自动转为 Y-up。
  if (sourceSize.z > sourceSize.y * 1.25 && sourceSize.z >= sourceSize.x) {
    modelRoot.rotation.x = Math.PI / 2;
  } else if (sourceSize.x > sourceSize.y * 1.25) {
    modelRoot.rotation.z = Math.PI / 2;
  }

  modelRoot.updateMatrixWorld(true);
  sourceBox = new THREE.Box3().setFromObject(modelRoot);
  sourceSize = sourceBox.getSize(new THREE.Vector3());
  const sourceHeight = sourceSize.y;

  if (Number.isFinite(sourceHeight) && sourceHeight > 0) {
    const targetRobotHeight = 8;
    const adaptiveScale = THREE.MathUtils.clamp(
      (targetRobotHeight / sourceHeight) * ROBOT_DISPLAY_SCALE,
      0.0001,
      100
    );
    modelRoot.scale.setScalar(adaptiveScale);
  }

  modelRoot.updateMatrixWorld(true);
  const fittedBox = new THREE.Box3().setFromObject(modelRoot);
  const center = fittedBox.getCenter(new THREE.Vector3());
  modelRoot.position.x -= center.x;
  modelRoot.position.z -= center.z;
  modelRoot.position.y -= fittedBox.min.y;

  modelRoot.traverse((child) => {
    if (!child.isMesh) return;
    const materials = Array.isArray(child.material) ? child.material : [child.material];
    materials.filter(Boolean).forEach((material) => {
      material.side = THREE.DoubleSide;
      material.opacity = 1;
      material.transparent = false;
      material.needsUpdate = true;
    });
  });
}

function clampCameraToClassroom() {
  if (!camera.value || !controls.value) return;
  const bounds = { minX: -68, maxX: 68, minY: 2, maxY: 34, minZ: -46, maxZ: 46 };
  camera.value.position.x = THREE.MathUtils.clamp(camera.value.position.x, bounds.minX, bounds.maxX);
  camera.value.position.y = THREE.MathUtils.clamp(camera.value.position.y, bounds.minY, bounds.maxY);
  camera.value.position.z = THREE.MathUtils.clamp(camera.value.position.z, bounds.minZ, bounds.maxZ);
  controls.value.target.x = THREE.MathUtils.clamp(controls.value.target.x, bounds.minX, bounds.maxX);
  controls.value.target.y = THREE.MathUtils.clamp(controls.value.target.y, 0, 24);
  controls.value.target.z = THREE.MathUtils.clamp(controls.value.target.z, bounds.minZ, bounds.maxZ);
}

function createMarker(type) {
  const geo = new THREE.CircleGeometry(2.6, 24);
  const mat = new THREE.MeshBasicMaterial({
    color: type === 'start' ? 0x2ecc71 : 0xe74c3c,
    transparent: true,
    opacity: 0.85,
    side: THREE.DoubleSide
  });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.rotation.x = -Math.PI / 2;
  mesh.position.set(0, 0.01, 0);
  mesh.visible = false;
  mesh.userData = { type };

  scene.value?.add(mesh);

  if (type === 'start') {
    startMarker.value = mesh;
  } else {
    endMarker.value = mesh;
  }
}

function disposeScene() {
  stopWalk();

  bumpSceneSession();

  if (animationId.value) {
  cancelAnimationFrame(animationId.value);
  animationId.value = 0;
  }

  unbindEvents();

  if (robotAnimationData.value) {
    robotAnimationData.value = null;
  }

  if (robotMixers.value.length) {
    robotMixers.value.forEach((mixer) => mixer.stopAllAction && mixer.stopAllAction());
    robotMixers.value = [];
  }
  robotActions.value = [];

  if (scene.value) {
    scene.value.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose());
        } else {
          obj.material.dispose();
        }
      }
    });
    scene.value.clear();
  }

  obstacleMeshes.value = [];
  defaultObstacleMeshes.value = [];
  obstacles.value = [];
  obstaclesByRect.value = [];

  if (renderer.value) {
    renderer.value.dispose();
    if (renderer.value.domElement && renderer.value.domElement.parentElement) {
      renderer.value.domElement.parentElement.removeChild(renderer.value.domElement);
    }
    renderer.value = null;
  }

  scene.value = null;
  camera.value = null;
  controls.value = null;
  robotGroup.value = null;
  robotModel.value = null;
  startMarker.value = null;
  endMarker.value = null;
  pathLine.value = null;
  gridHelper.value = null;
  groundMesh.value = null;
  drawPreview.value = null;
  drawStart.value = null;
  isDrawing.value = false;
}

function bindEvents() {
  if (!renderer.value?.domElement) return;

  renderer.value.domElement.addEventListener('pointerdown', onPointerDown);
  renderer.value.domElement.addEventListener('pointermove', onPointerMove);
  renderer.value.domElement.addEventListener('pointerup', onPointerUp);
  window.addEventListener('resize', onWindowResize);
}

function unbindEvents() {
  if (!renderer.value?.domElement) return;

  renderer.value.domElement.removeEventListener('pointerdown', onPointerDown);
  renderer.value.domElement.removeEventListener('pointermove', onPointerMove);
  renderer.value.domElement.removeEventListener('pointerup', onPointerUp);
  window.removeEventListener('resize', onWindowResize);
}

function onWindowResize() {
  if (!sceneContainer.value || !renderer.value || !camera.value) return;
  const w = sceneContainer.value.clientWidth;
  const h = sceneContainer.value.clientHeight;
  camera.value.aspect = w / h;
  camera.value.updateProjectionMatrix();
  renderer.value.setSize(w, h);
}

function updateStatus() {
  const robotPosText = robotModel.value
    ? `机器人坐标（x:${robotModel.value.position.x.toFixed(1)} z:${robotModel.value.position.z.toFixed(1)}）`
    : '机器人未放置';

  statusText.value = `${statusHintByMode.value} ｜ ${robotPosText}`;
}

function getGroundPoint(event) {
  if (!renderer.value || !camera.value || !groundMesh.value) return null;

  const rect = renderer.value.domElement.getBoundingClientRect();
  if (!rect || rect.width === 0 || rect.height === 0) return null;

  const clientX = event?.clientX;
  const clientY = event?.clientY;
  if (typeof clientX !== 'number' || typeof clientY !== 'number') return null;

  pointer.value.set(
    ((clientX - rect.left) / rect.width) * 2 - 1,
    -((clientY - rect.top) / rect.height) * 2 + 1
  );

  raycaster.value.setFromCamera(pointer.value, camera.value);

  const intersects = raycaster.value.intersectObject(groundMesh.value, true);
  if (!intersects || intersects.length === 0) return null;

  const hit = intersects[0].point;
  return {
    x: hit.x,
    y: hit.y,
    z: hit.z
  };
}

function updateHoverPoint(event) {
  const point = getGroundPoint(event);
  if (point) {
    hoverPoint.value.set(point.x, point.z);
    hoverPointText.value = `x:${point.x.toFixed(2)} , z:${point.z.toFixed(2)}`;
  } else {
    hoverPointText.value = '';
  }
}

function setPlacementMode(mode) {
  placementMode.value = mode;
  drawingMode.value = false;
  statusText.value = mode === 'start' ? '当前将下一次点击作为起点' : '当前将下一次点击作为终点';
}

function setStart(point) {
  const p = { x: point.x, y: 0, z: point.z };
  startPoint.value = p;

  if (!startMarker.value) return;
  startMarker.value.position.set(p.x, 0.02, p.z);
  startMarker.value.visible = true;

  updateStatus();
}

function setEnd(point) {
  const p = { x: point.x, y: 0, z: point.z };
  endPoint.value = p;
  if (!endMarker.value) return;
  endMarker.value.position.set(p.x, 0.02, p.z);
  endMarker.value.visible = true;
  updateStatus();
}

function clearPoints() {
  startPoint.value = null;
  endPoint.value = null;
  if (startMarker.value) startMarker.value.visible = false;
  if (endMarker.value) endMarker.value.visible = false;
  clearCurrentPath();
  if (!robotGroup.value) {
    robotLoaded.value = false;
  }
  statusText.value = '已清空起点和终点';
}

function clearCurrentPath() {
  disposePathLine();
  currentPath.value = [];
}

function disposePathLine() {
  if (pathLine.value) {
    scene.value.remove(pathLine.value);
    if (pathLine.value.geometry) pathLine.value.geometry.dispose();
    if (pathLine.value.material) pathLine.value.material.dispose();
    pathLine.value = null;
  }
}

function normalizeRect(p1, p2) {
  const minX = Math.min(p1.x, p2.x);
  const maxX = Math.max(p1.x, p2.x);
  const minZ = Math.min(p1.z, p2.z);
  const maxZ = Math.max(p1.z, p2.z);
  return { minX, maxX, minZ, maxZ };
}

function createClassroomObstaclesFromBounds(bounds) {
  const size = bounds.getSize(new THREE.Vector3());
  const center = bounds.getCenter(new THREE.Vector3());
  const width = size.x;
  const depth = size.z;
  const deskHalfWidth = Math.max(1.4, width * 0.035);
  const deskHalfDepth = Math.max(2.4, depth * 0.022);

  const podium = {
    id: 'default-podium',
    name: '讲台',
    minX: center.x - width * 0.18,
    maxX: center.x + width * 0.18,
    minZ: center.z - depth * 0.44,
    maxZ: center.z - depth * 0.36
  };

  const desks = Array.from({ length: 4 }, (_, row) =>
    Array.from({ length: 5 }, (_, col) => {
      const x = center.x + (col - 2) * width * 0.16;
      const z = center.z + (row - 1.5) * depth * 0.18;
      return {
        id: `default-desk-${row}-${col}`,
        name: `第${row + 1}排第${col + 1}组桌椅`,
        minX: x - deskHalfWidth,
        maxX: x + deskHalfWidth,
        minZ: z - deskHalfDepth,
        maxZ: z + deskHalfDepth
      };
    })
  ).flat();

  return [podium, ...desks].map((item) => ({
    ...item,
    locked: true,
    source: 'classroom-default'
  }));
}

function rebuildDefaultClassroomObstacles(bounds) {
  if (!bounds || bounds.isEmpty()) return;
  defaultObstacleMeshes.value.forEach((mesh) => {
    scene.value?.remove(mesh);
    mesh.geometry?.dispose();
    mesh.material?.dispose();
  });
  defaultObstacleMeshes.value = [];
  obstacles.value = obstacles.value.filter((item) => !item.locked);
  obstaclesByRect.value = obstaclesByRect.value.filter((item) => !item.locked);

  createClassroomObstaclesFromBounds(bounds).forEach((item) => {
    if (obstacles.value.some((obstacle) => obstacle.id === item.id)) return;
    const obstacle = { ...item };
    obstacles.value.push(obstacle);
    obstaclesByRect.value.push(obstacle);
    if (scene.value) {
      const mesh = createObstacleMesh(obstacle, false, true);
      scene.value.add(mesh);
      defaultObstacleMeshes.value.push(mesh);
    }
  });
}

function createObstacleMesh(rect, isPreview = false, isDefault = false) {
  const w = Math.max(1, rect.maxX - rect.minX);
  const h = Math.max(1, rect.maxZ - rect.minZ);

  const material = new THREE.MeshStandardMaterial({
    color: isPreview ? 0xffa500 : isDefault ? 0xff2638 : 0xd35400,
    transparent: true,
    opacity: isPreview ? 0.45 : isDefault ? 0.22 : 0.6,
    depthWrite: !isDefault
  });

  const obstacleHeight = isDefault ? 1.2 : 0.5;
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, obstacleHeight, h), material);
  mesh.position.set((rect.minX + rect.maxX) / 2, obstacleHeight / 2 + 0.03, (rect.minZ + rect.maxZ) / 2);
  mesh.name = isPreview ? 'obstacle-preview' : isDefault ? `default-obstacle-${rect.name}` : 'obstacle';
  mesh.userData.block = true;
  return mesh;
}

function toggleDrawObstacleMode() {
  drawingMode.value = !drawingMode.value;
  if (drawingMode.value) {
    statusText.value = '进入障碍物绘制模式：请按住左键并拖拽';
  } else {
    removeDrawPreview();
    statusText.value = '已退出障碍物绘制模式';
  }
}

function removeDrawPreview() {
  if (drawPreview.value) {
    scene.value.remove(drawPreview.value);
    if (drawPreview.value.geometry) drawPreview.value.geometry.dispose();
    if (drawPreview.value.material) drawPreview.value.material.dispose();
    drawPreview.value = null;
  }
  drawStart.value = null;
  isDrawing.value = false;
}

function onPointerDown(event) {
  if (!scene.value || !renderer.value || !camera.value) return;
  if (event.button !== 0) return;

  const point = getGroundPoint(event);
  if (!point) return;

  if (drawingMode.value) {
    drawStart.value = point;
    isDrawing.value = true;
    if (drawPreview.value) {
      scene.value.remove(drawPreview.value);
      if (drawPreview.value.geometry) drawPreview.value.geometry.dispose();
      if (drawPreview.value.material) drawPreview.value.material.dispose();
    }
    drawPreview.value = createObstacleMesh({ minX: point.x, maxX: point.x, minZ: point.z, maxZ: point.z }, true);
    scene.value.add(drawPreview.value);
    return;
  }

  if (placementMode.value === 'start') {
    setStart(point);
    return;
  }

  if (placementMode.value === 'end') {
    setEnd(point);
    return;
  }

  if (!startPoint.value) {
    setStart(point);
  } else {
    setEnd(point);
  }
}

function onPointerMove(event) {
  if (renderer.value && renderer.value.domElement) {
    updateHoverPoint(event);
  }

  if (!isDrawing.value || !drawStart.value || !drawPreview.value) return;

  const point = getGroundPoint(event);
  if (!point) return;

  const nextRect = normalizeRect(drawStart.value, point);
  drawPreview.value.geometry?.dispose();
  drawPreview.value.geometry = createObstacleMesh(nextRect, true).geometry;
  drawPreview.value.material?.color.set(0xffa500);
  drawPreview.value.material.opacity = 0.45;
  drawPreview.value.position.set((nextRect.minX + nextRect.maxX) / 2, 0.25, (nextRect.minZ + nextRect.maxZ) / 2);
  drawPreview.value.scale.set(1, 1, 1);
}

function onPointerUp(event) {
  if (!drawingMode.value || !isDrawing.value || !drawStart.value) {
    isDrawing.value = false;
    return;
  }

  const point = getGroundPoint(event);
  if (!point) {
    removeDrawPreview();
    return;
  }

  const rect = normalizeRect(drawStart.value, point);
  isDrawing.value = false;

  if (rect.maxX - rect.minX < 1 || rect.maxZ - rect.minZ < 1) {
    removeDrawPreview();
    return;
  }

  const obstacle = {
    id: Date.now(),
    minX: rect.minX,
    maxX: rect.maxX,
    minZ: rect.minZ,
    maxZ: rect.maxZ
  };

  obstacles.value.push(obstacle);
  obstaclesByRect.value = [...obstaclesByRect.value, obstacle];

  if (drawPreview.value) {
    scene.value.remove(drawPreview.value);
    if (drawPreview.value.geometry) drawPreview.value.geometry.dispose();
    if (drawPreview.value.material) drawPreview.value.material.dispose();
  }
  drawPreview.value = null;

  const mesh = createObstacleMesh(rect);
  scene.value.add(mesh);
  obstacleMeshes.value.push(mesh);
  drawStart.value = null;

  // 绘制完成后自动保存
  toLocalStorage(OBSTACLE_KEY, obstacles.value.filter((item) => !item.locked));
  statusText.value = `已新增障碍物，当前障碍物：${obstacles.value.length}`;
}


function undoObstacle() {
  const removableIndex = obstacles.value.findLastIndex((item) => !item.locked);
  const removed = removableIndex >= 0 ? obstacles.value.splice(removableIndex, 1)[0] : null;
  if (!removed) {
    statusText.value = '当前没有可撤销的自定义障碍物';
    return;
  }

  const removedMesh = obstacleMeshes.value.pop();
  if (removedMesh) {
    scene.value.remove(removedMesh);
    if (removedMesh.geometry) removedMesh.geometry.dispose();
    if (removedMesh.material) removedMesh.material.dispose();
  }

  obstaclesByRect.value = obstaclesByRect.value.filter((item) => item.id !== removed.id);
  toLocalStorage(OBSTACLE_KEY, obstacles.value.filter((item) => !item.locked));
  statusText.value = `已撤销一块障碍，当前障碍物：${obstacles.value.length}`;
}

function clearAllObstacles() {
  if (!obstacleMeshes.value.length && obstacles.value.every((item) => item.locked)) {
    statusText.value = '当前没有自定义障碍物，讲台和桌椅障碍已保留';
    return;
  }

  obstacleMeshes.value.forEach((mesh) => {
    scene.value.remove(mesh);
    if (mesh.geometry) mesh.geometry.dispose();
    if (mesh.material) mesh.material.dispose();
  });

  obstacleMeshes.value = [];
  obstacles.value = obstacles.value.filter((item) => item.locked);
  obstaclesByRect.value = [...obstacles.value];
  if (drawPreview.value) {
    scene.value.remove(drawPreview.value);
    if (drawPreview.value.geometry) drawPreview.value.geometry.dispose();
    if (drawPreview.value.material) drawPreview.value.material.dispose();
    drawPreview.value = null;
  }

  localStorage.removeItem(OBSTACLE_KEY);
  statusText.value = '自定义障碍物已清空，讲台和桌椅仍作为默认障碍物';
}

function saveObstacles() {
  const customObstacles = obstacles.value.filter((item) => !item.locked);
  toLocalStorage(OBSTACLE_KEY, customObstacles);
  statusText.value = `自定义障碍数据已写入本地，共 ${customObstacles.length} 条`;
}

function exportObstacles() {
  const data = JSON.stringify(obstacles.value.filter((item) => !item.locked), null, 2);
  const blob = new Blob([data], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `obstacles-${Date.now()}.json`;
  a.click();
  URL.revokeObjectURL(url);
}

function triggerObstacleImport() {
  obstacleFileInputRef.value?.click();
}

function importObstacles(event) {
  const file = event.target.files && event.target.files[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = () => {
    try {
      const parsed = JSON.parse(reader.result);
      if (!Array.isArray(parsed)) throw new Error('JSON 格式错误');

      const filtered = parsed
        .filter((item) => item && Number.isFinite(item.minX) && Number.isFinite(item.maxX)
          && Number.isFinite(item.minZ) && Number.isFinite(item.maxZ))
        .map((item) => ({
          id: item.id || Date.now() + Math.random(),
          minX: Math.min(item.minX, item.maxX),
          maxX: Math.max(item.minX, item.maxX),
          minZ: Math.min(item.minZ, item.maxZ),
          maxZ: Math.max(item.minZ, item.maxZ)
        }));

      clearAllObstacles();

      filtered.forEach((rect) => {
        obstacles.value.push(rect);
        obstaclesByRect.value.push(rect);
        const mesh = createObstacleMesh(rect);
        scene.value.add(mesh);
        obstacleMeshes.value.push(mesh);
      });

      toLocalStorage(OBSTACLE_KEY, obstacles.value);
      statusText.value = `导入成功，障碍物数：${obstacles.value.length}`;
    } catch (error) {
      console.error('导入障碍物失败：', error);
      statusText.value = '导入障碍物失败，请检查 JSON 格式';
    }
  };

  reader.readAsText(file);
  event.target.value = '';
}

function loadSavedObstacles() {
  const saved = fromLocalStorage(OBSTACLE_KEY);
  if (!Array.isArray(saved)) return;

  saved.forEach((item) => {
    if (!item || item.locked || item.source === 'classroom-default' || !Number.isFinite(item.minX)) return;
    const obstacle = {
      id: item.id || Date.now() + Math.random(),
      minX: Math.min(item.minX, item.maxX),
      maxX: Math.max(item.minX, item.maxX),
      minZ: Math.min(item.minZ, item.maxZ),
      maxZ: Math.max(item.minZ, item.maxZ)
    };
    obstacles.value.push(obstacle);
    obstaclesByRect.value.push(obstacle);
    const mesh = createObstacleMesh(obstacle);
    scene.value.add(mesh);
    obstacleMeshes.value.push(mesh);
  });
}

function getPlannerBounds() {
  const worldLimit = 90;
  let minX = -worldLimit;
  let maxX = worldLimit;
  let minZ = -worldLimit;
  let maxZ = worldLimit;

  if (startPoint.value) {
    minX = Math.min(minX, startPoint.value.x - 80);
    maxX = Math.max(maxX, startPoint.value.x + 80);
    minZ = Math.min(minZ, startPoint.value.z - 80);
    maxZ = Math.max(maxZ, startPoint.value.z + 80);
  }

  if (endPoint.value) {
    minX = Math.min(minX, endPoint.value.x - 80);
    maxX = Math.max(maxX, endPoint.value.x + 80);
    minZ = Math.min(minZ, endPoint.value.z - 80);
    maxZ = Math.max(maxZ, endPoint.value.z + 80);
  }

  for (const obs of obstacles.value) {
    minX = Math.min(minX, obs.minX - 80);
    maxX = Math.max(maxX, obs.maxX + 80);
    minZ = Math.min(minZ, obs.minZ - 80);
    maxZ = Math.max(maxZ, obs.maxZ + 80);
  }

  return {
    min: { x: minX, z: minZ },
    max: { x: maxX, z: maxZ }
  };
}

function checkSegmentCollision(p1, p2) {
  const padding = 2;
  const dx = p2.x - p1.x;
  const dz = p2.z - p1.z;
  const dist = Math.sqrt(dx * dx + dz * dz);
  const steps = Math.max(Math.ceil(dist / 3), 20);

  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const x = p1.x + dx * t;
    const z = p1.z + dz * t;

    for (const o of obstacles.value) {
      if (x >= o.minX - padding && x <= o.maxX + padding && z >= o.minZ - padding && z <= o.maxZ + padding) {
        return true;
      }
    }
  }

  return false;
}

function hasPointInObstacle(p, padding = 0) {
  return obstacles.value.some((o) =>
    p.x >= o.minX - padding && p.x <= o.maxX + padding
      && p.z >= o.minZ - padding && p.z <= o.maxZ + padding);
}

function planPath() {
  if (!endPoint.value) {
    statusText.value = '请先标记终点，机器人当前位置会自动作为起点';
    return;
  }

  const physicalStart = robotGroup.value
    ? { x: robotGroup.value.position.x, y: 0, z: robotGroup.value.position.z }
    : startPoint.value;

  if (!physicalStart) {
    statusText.value = '机器人尚未加载，请等待模型加载完成';
    return;
  }

  startPoint.value = physicalStart;
  if (startMarker.value) {
    startMarker.value.position.set(physicalStart.x, 0.02, physicalStart.z);
    startMarker.value.visible = true;
  }

  if (hasPointInObstacle(physicalStart) || hasPointInObstacle(endPoint.value)) {
    statusText.value = '起点或终点位于障碍物中，请重新放置';
    return;
  }

  statusText.value = '正在进行 A* 避障路径规划...';
  let path;
  try {
    const planner = new PathPlanner({
      obstacles: obstacles.value,
      robotRadius: 1.3,
      bounds: getPlannerBounds(),
      gridSize: 1.5,
      groundHeight: 0
    });

    path = planner.plan(
      { x: physicalStart.x, z: physicalStart.z },
      { x: endPoint.value.x, z: endPoint.value.z }
    );
  } catch (error) {
    console.error('A* 路径规划失败：', error);
    clearCurrentPath();
    statusText.value = `A* 路径规划失败：${error?.message || '未知错误'}`;
    return;
  }

  if (!path || path.length < 2) {
    statusText.value = '当前场景未找到可行路径，请调整障碍物';
    return;
  }

  let valid = true;
  for (let i = 1; i < path.length; i++) {
    if (checkSegmentCollision(path[i - 1], path[i])) {
      valid = false;
      break;
    }
  }

  if (!valid) {
    clearCurrentPath();
    statusText.value = '没有找到可安全通行的路线，请调整起点、终点或自定义障碍物';
    return;
  }

  currentPath.value = path.map((point) => ({ x: point.x, y: 0, z: point.z }));
  drawPath(currentPath.value, true);
  statusText.value = 'A* 避障规划成功，机器人可沿安全路径运动';
}

function drawPath(points, safe) {
  disposePathLine();

  const positions = [];
  points.forEach((p) => positions.push(p.x, p.y, p.z));

  const material = new THREE.LineBasicMaterial({
    color: safe ? 0x00bcd4 : 0xe74c3c,
    linewidth: 3
  });

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));

  const line = new THREE.Line(geometry, material);
  pathLine.value = line;
  scene.value.add(line);
}

function walkPath() {
  if (currentPath.value.length < 2) {
    statusText.value = '请先生成路线';
    return;
  }

  if (!robotGroup.value) {
    statusText.value = '机器人未放置，无法行走';
    return;
  }
  stopWalk();
  walkIndex.value = 1;
  robotCurrentSpeed = 0;
  isWalking.value = true;
  robotGroups.value.forEach((group) => {
    if (group) group.position.y = robotYOffset;
  });

  playRobotWalkAction();
  statusText.value = '机器人开始巡检';
}

function stopWalk() {
  isWalking.value = false;
  robotCurrentSpeed = 0;
  stopRobotWalkAction();
}

function saveRoutesToStorage() {
  toLocalStorage(ROUTE_KEY, routes.value);
}

async function loadRoutesFromStorage() {
  let saved = null;
  try {
    const response = await axios.get('/api/rsm/classroom/route/list');
    saved = (response.data.rows || []).map((row) => {
      const data = JSON.parse(row.route_data || '{}');
      return { ...data, id: row.id, name: row.route_name };
    });
  } catch (error) {
    console.warn('共享数据库中的路线加载失败，使用本地缓存：', error);
    saved = fromLocalStorage(ROUTE_KEY);
  }
  if (!Array.isArray(saved)) return;
  routes.value = saved
    .filter((item) => item && item.id && Array.isArray(item.path) && item.path.length >= 2)
    .map((item) => ({
      ...item,
      path: item.path.map((p) => ({ x: Number(p.x), y: 0, z: Number(p.z) })).filter((p) => Number.isFinite(p.x) && Number.isFinite(p.z))
    }));
}

async function saveCurrentRoute() {
  const routeName = window.prompt('请输入路线名称', `路线_${new Date().toLocaleString()}`);
  if (!routeName) return;

  if (!startPoint.value || !endPoint.value || currentPath.value.length < 2) {
    statusText.value = '请先设置起点、终点并生成路径后再保存';
    return;
  }

  const route = {
    id: Date.now(),
    name: routeName,
    start: { x: startPoint.value.x, z: startPoint.value.z },
    end: { x: endPoint.value.x, z: endPoint.value.z },
    path: currentPath.value.map((p) => ({ x: p.x, z: p.z }))
  };

  try {
    await axios.post('/api/rsm/classroom/route', {
      routeName,
      routeData: JSON.stringify(route),
      obstacleData: JSON.stringify(obstacles.value.filter((item) => !item.locked))
    });
    await loadRoutesFromStorage();
  } catch (error) {
    routes.value.unshift(route);
    console.warn('路线写入共享数据库失败，已保存到本地缓存：', error);
  }

  saveRoutesToStorage();
  statusText.value = `路线已保存：${routeName}`;
}

async function deleteRoute(id) {
  try {
    await axios.delete(`/api/rsm/classroom/route/${id}`);
  } catch (error) {
    console.warn('共享数据库中的路线删除失败，仅删除本地缓存：', error);
  }
  routes.value = routes.value.filter((item) => item.id !== id);
  saveRoutesToStorage();
}

function runSavedRoute(route) {
  loadRoute(route);
  planPath();
  walkPath();
}

function loadRoute(route) {
  if (!route) return;

  setStart(route.start);
  setEnd(route.end);

  const loadedPath = route.path
    .filter((item) => Number.isFinite(item.x) && Number.isFinite(item.z))
    .map((item) => ({ x: item.x, y: 0, z: item.z }));

  if (!loadedPath.length) {
    statusText.value = '该路线无可用路径';
    return;
  }

  currentPath.value = loadedPath;
  drawPath(loadedPath, true);
  statusText.value = `已加载路线：${route.name}`;
}

function reloadScene() {
  disposeScene();
  clearCurrentPath();
  startPoint.value = null;
  endPoint.value = null;
  isWalking.value = false;
  drawingMode.value = false;
  if (startMarker.value) startMarker.value.visible = false;
  if (endMarker.value) endMarker.value.visible = false;
  if (startMarker.value) startMarker.value = null;
  if (endMarker.value) endMarker.value = null;

  initScene();
  loadSavedObstacles();
}

function initRobotPlaceholder() {
  if (robotGroup.value) return;

  const sphere = new THREE.Mesh(
    new THREE.CylinderGeometry(2, 2, 4, 16),
    new THREE.MeshStandardMaterial({ color: 0x0fbcf9 })
  );
  sphere.rotation.x = Math.PI / 2;
  robotGroup.value = new THREE.Group();
  robotGroup.value.add(sphere);
  scene.value.add(robotGroup.value);
  robotYOffset = 2;
  robotLoaded.value = true;
}

const loadModels = async () => {
  if (loadingModel.value) return;
  loadingModel.value = true;
  statusText.value = `加载 ${modelStatusHint} 下的全部模型并初始化...`;

  const sessionId = sceneSessionId;
  const fbxLoader = new FBXLoader();
  const gltfLoader = new GLTFLoader();

  const loadByUrl = (url) => {
    return new Promise((resolve, reject) => {
      const lowerUrl = url.toLowerCase();
      const normalized = {
        url,
        root: null,
        animations: []
      };

      const onLoaded = (payload) => {
        if (!payload) {
          reject(new Error(`模型资源为空：${url}`));
          return;
        }

        if (lowerUrl.endsWith('.gltf') || lowerUrl.endsWith('.glb')) {
          normalized.root = payload?.scene || payload?.scenes?.[0] || null;
          normalized.animations = Array.isArray(payload?.animations) ? payload.animations : [];
        } else {
          normalized.root = payload;
          normalized.animations = Array.isArray(payload?.animations) ? payload?.animations : [];
        }

        if (!normalized.root) {
          reject(new Error(`模型资源为空：${url}`));
          return;
        }

        return resolve(normalized);
      };

      const onError = (error) => reject(error);

      if (lowerUrl.endsWith('.gltf') || lowerUrl.endsWith('.glb')) {
        gltfLoader.load(url, onLoaded, undefined, onError);
      } else {
        fbxLoader.load(url, onLoaded, undefined, onError);
      }
    });
  };

  const classify = (url) => {
    if (isRobotModelFile(url)) {
      return 'robot';
    }

    if (isWalkAnimationFile(url)) {
      return 'animation';
    }

    if (isSceneModelFile(url)) {
      return 'scene';
    }

    return 'unknown';
  };

  let sceneLoadedCount = 0;
  let unknownLoadedCount = 0;

  const allModelFiles = dedupeModelFiles(MODEL_FILES);
  if (!allModelFiles.length) {
    if (!robotGroup.value) {
      initRobotPlaceholder();
    }
    robotLoaded.value = true;
    loadingModel.value = false;
    modelLoadError.value = '未找到可用模型文件';
    statusText.value = modelLoadError.value;
    return;
  }

      const loadPromises = allModelFiles.map((url) =>
    loadByUrl(url)
      .then((asset) => ({ status: 'ok', url, asset }))
      .catch((error) => ({
        status: 'error',
        url,
        error: {
          name: error?.name || 'UnknownError',
          message: error?.message || String(error)
        }
      }))
  );

  Promise.all(loadPromises)
    .then((results) => {
      if (!isCurrentSceneSession(sessionId) || !scene.value) return;

      if (!results.some((item) => item.status === 'ok')) {
        modelLoadError.value = '未加载到任何模型';
        statusText.value = modelLoadError.value;
        initRobotPlaceholder();
        robotLoaded.value = true;
        return;
      }

      robotGroups.value = [];
      robotMixers.value = [];
      robotActions.value = [];
      modelGroups.length = 0;
      Object.keys(modelGroupIndex).forEach((key) => {
        delete modelGroupIndex[key];
      });

      const loadErrors = [];
      results.forEach((result) => {
        if (result.status === 'error') {
          const errorMessage = result.error && result.error.message ? result.error.message : '未知错误';
          loadErrors.push(`${result.url}（${errorMessage}）`);
          return;
        }

        const loaded = result.asset;
        const className = classify(result.url);

        if (className === 'animation') {
          const clip = pickWalkClip(loaded);
          if (clip) {
            robotAnimationData.value = { clip, source: loaded.url, duration: clip.duration };
          }
          return;
        }

        if (className === 'robot') {
          const robotGroupItem = markRaw(new THREE.Group());
          const robotIndex = robotGroups.value.length;
          robotGroupItem.name = `robot-${robotIndex}`;
          robotGroupItem.position.set(robotIndex * ROBOT_GROUP_OFFSET_X, 0, 0);

          fitRobotModel(loaded.root);
          robotGroupItem.add(loaded.root);

          const added = safeAddToScene(robotGroupItem, sessionId);
          if (!added) return;

          const mixer = new THREE.AnimationMixer(loaded.root);
          robotMixers.value.push(mixer);
          robotActions.value.push(null);
          robotGroups.value.push(robotGroupItem);

          const embeddedWalkClip = makeClipInPlace(pickWalkClip(loaded));
          if (embeddedWalkClip) {
            robotAnimationData.value = {
              clip: embeddedWalkClip,
              source: loaded.url,
              duration: embeddedWalkClip.duration
            };
          }

          if (!robotGroup.value) {
            robotGroup.value = robotGroupItem;
            robotModel.value = loaded.root;
            robotYOffset = 0;
          }

          return;
        }

        if (className === 'scene') {
          const sceneGroup = markRaw(new THREE.Group());
          sceneGroup.name = `scene-${sceneLoadedCount}`;
          sceneGroup.position.set(sceneLoadedCount * SCENE_MODEL_OFFSET_X, 0, 0);
          const sceneBounds = fitSceneModel(loaded.root);
          sceneGroup.add(loaded.root);
          sceneLoadedCount += 1;
          if (safeAddToScene(sceneGroup, sessionId)) {
            modelGroups.push(sceneGroup);
            rebuildDefaultClassroomObstacles(sceneBounds);
          }
          return;
        }

        const extraGroup = markRaw(new THREE.Group());
        extraGroup.name = `unknown-${unknownLoadedCount}`;
        loaded.root.scale.setScalar(SCENE_SCALE.default);
        extraGroup.position.set(unknownLoadedCount * SCENE_MODEL_OFFSET_X, 0, 0);
        unknownLoadedCount += 1;
        extraGroup.add(loaded.root);
        safeAddToScene(extraGroup, sessionId);
      });

      bindWalkAnimationToRobotGroups();

      if (robotGroups.value.length === 0) {
        initRobotPlaceholder();
      }

      modelLoadError.value = '';
      robotLoaded.value = true;

      const countOk = results.filter((item) => item.status === 'ok').length;
      const countAll = results.length;
      const sceneModelLoaded = results.filter((item) => item.status === 'ok' && classify(item.url) === 'scene').length;
      const robotModelLoaded = results.filter((item) => item.status === 'ok' && classify(item.url) === 'robot').length;
      const extraModelLoaded = results.filter((item) => item.status === 'ok' && classify(item.url) === 'unknown').length;
          const walkClipInfo = robotAnimationData.value?.clip
        ? `行走动画：${robotAnimationData.value.source}（${(robotAnimationData.value.duration || 0).toFixed(2)}s）`
        : '未检测到行走动画';

      const failedCount = loadErrors.length;
      const failHint = failedCount > 0 ? `；失败 ${failedCount} 个` : '';

      if (loadErrors.length > 0) {
        modelLoadError.value = `部分模型加载失败（${failedCount}个）：${loadErrors.join('，')}`;
        console.warn('部分模型加载失败', loadErrors);
      } else {
        modelLoadError.value = '';
      }

      statusText.value = `已加载 ${countOk}/${countAll} 个文件；场景 ${sceneModelLoaded}，机器人 ${robotModelLoaded}，其他 ${extraModelLoaded}；${walkClipInfo}${failHint}`;
    })
    .catch((error) => {
      console.error('模型加载失败：', error);
      modelLoadError.value = `模型加载流程异常，请确认 ${SCENE_DIRECTORY_PATH} 与 ${ROBOT_DIRECTORY_PATH} 下模型文件是否可访问`;
      statusText.value = modelLoadError.value;

      if (!robotGroup.value) {
        initRobotPlaceholder();
      }
    })
    .finally(() => {
      loadingModel.value = false;
    });
}
function focusRobot() {
  if (!robotGroup.value || !camera.value || !controls.value) {
    statusText.value = '暂无可聚焦机器人';
    return;
  }

  const pos = robotGroup.value.position;
  controls.value.target.set(pos.x, 4, pos.z);
  camera.value.position.set(pos.x + 18, 15, pos.z + 24);
  clampCameraToClassroom();
  controls.value.update();
}
const animate = (sessionId) => {
  if (!isCurrentSceneSession(sessionId)) {
    return;
  }

  animationId.value = requestAnimationFrame(() => animate(sessionId));

  if (!scene.value || !renderer.value || !camera.value || !clock.value) {
    return;
  }

  if (scene.value === null || renderer.value === null || camera.value === null) {
    return;
  }

  const delta = clock.value.getDelta();
  controls.value?.update();
  clampCameraToClassroom();

  robotMixers.value.forEach((mixer) => {
    if (mixer) {
      mixer.update(delta);
    }
  });

  robotGroups.value.forEach((group) => {
    if (group) group.position.y = robotYOffset;
  });

  if (isWalking.value && currentPath.value.length > 1 && robotGroup.value) {
    const target = currentPath.value[walkIndex.value];
    const robotPos = robotGroup.value.position;
    const dir = new THREE.Vector3(target.x - robotPos.x, 0, target.z - robotPos.z);
    const distance = dir.length();

    if (distance < 0.15) {
      walkIndex.value += 1;

      if (walkIndex.value >= currentPath.value.length) {
        isWalking.value = false;
        robotCurrentSpeed = 0;
        statusText.value = '到达终点，巡检完成';
        stopRobotWalkAction();
      }
    } else {
      dir.normalize();
      const maxSpeed = currentPathSpeed();
      const brakingSpeed = Math.sqrt(2 * ROBOT_ACCELERATION * distance);
      const targetSpeed = Math.min(maxSpeed, brakingSpeed);
      if (robotCurrentSpeed < targetSpeed) {
        robotCurrentSpeed = Math.min(targetSpeed, robotCurrentSpeed + ROBOT_ACCELERATION * delta);
      } else {
        robotCurrentSpeed = Math.max(targetSpeed, robotCurrentSpeed - ROBOT_ACCELERATION * delta);
      }
      const speed = Math.max(0.35, robotCurrentSpeed);
      robotActions.value.forEach((action) => {
        if (action) action.timeScale = THREE.MathUtils.clamp(speed / maxSpeed, 0.55, 1.15);
      });
      const primaryStep = Math.min(speed * delta, distance);
      const nextPosition = {
        x: robotPos.x + dir.x * primaryStep,
        z: robotPos.z + dir.z * primaryStep
      };

      if (hasPointInObstacle(nextPosition, 1.3)) {
        stopWalk();
        statusText.value = '前方检测到讲台或桌椅障碍，机器人已停止，请重新规划路线';
        renderer.value.render(scene.value, camera.value);
        return;
      }

      robotGroups.value.forEach((group, idx) => {
        if (!group) return;

        const offset = idx * 4;
        const targetX = target.x + offset;
        const targetZ = target.z;

        const moveX = targetX - group.position.x;
        const moveZ = targetZ - group.position.z;
        const moveDistance = Math.sqrt(moveX * moveX + moveZ * moveZ);

        if (moveDistance < 0.15) {
          return;
        }

        const step = Math.min(1, (speed * delta) / moveDistance);
        group.position.x += moveX * step;
        group.position.z += moveZ * step;
        group.position.y = robotYOffset;
        group.rotation.y = Math.atan2(moveX, moveZ);
      });

    }
  }

  renderer.value.render(scene.value, camera.value);
};
function currentPathSpeed() {
  return currentAnimationSpeed * 20;
}

function loadDefaults() {
  if (scene.value) {
    loadSavedObstacles();
  }
  loadRoutesFromStorage();
}

onUnmounted(() => {
  disposeScene();
});

onMounted(() => {
  initScene();
  loadDefaults();
  updateStatus();
});
</script>

