export class PathPlanner {
  constructor(options = {}) {
    this.robotRadius = options.robotRadius || 30;
    this.obstacles = options.obstacles || [];
    this.bounds = options.bounds || null;
    this.groundHeight = options.groundHeight || 0;
    this.gridSize = options.gridSize || 20;

    this.grid = null;
    this.gridWidth = 0;
    this.gridHeight = 0;
    this.gridOffsetX = 0;
    this.gridOffsetZ = 0;
  }

  plan(start, goal) {
    console.log("=== A* 路径规划开始 ===");
    console.log("起点:", start);
    console.log("终点:", goal);
    console.log("障碍物数量:", this.obstacles.length);

    if (!this.bounds) {
      this.bounds = this.calculateDefaultBounds(start, goal);
    }

    this.buildGrid();

    const startGrid = this.worldToGrid(start.x, start.z);
    const goalGrid = this.worldToGrid(goal.x, goal.z);

    console.log("网格尺寸:", this.gridWidth, "x", this.gridHeight);
    console.log("起点网格:", startGrid);
    console.log("终点网格:", goalGrid);

    const pathGrid = this.aStarSearch(startGrid, goalGrid);

    if (!pathGrid || pathGrid.length === 0) {
      console.warn("A*未找到路径");
      return this.generateDirectPath(start, goal);
    }

    const smoothedPath = this.smoothPath(pathGrid);

    const worldPath = smoothedPath.map(p => ({
      x: this.gridToWorldX(p.x),
      y: this.groundHeight,
      z: this.gridToWorldZ(p.z)
    }));

    worldPath.unshift({ x: start.x, y: this.groundHeight, z: start.z });
    worldPath.push({ x: goal.x, y: this.groundHeight, z: goal.z });

    const finalPath = this.removeRedundantPoints(worldPath);

    console.log("=== A* 路径规划完成 ===");
    console.log("路径点数:", finalPath.length);

    return finalPath;
  }

  calculateDefaultBounds(start, goal) {
    const padding = 500;
    let minX = Math.min(start.x, goal.x) - padding;
    let maxX = Math.max(start.x, goal.x) + padding;
    let minZ = Math.min(start.z, goal.z) - padding;
    let maxZ = Math.max(start.z, goal.z) + padding;

    for (const obs of this.obstacles) {
      minX = Math.min(minX, obs.minX - padding);
      maxX = Math.max(maxX, obs.maxX + padding);
      minZ = Math.min(minZ, obs.minZ - padding);
      maxZ = Math.max(maxZ, obs.maxZ + padding);
    }

    return { min: { x: minX, z: minZ }, max: { x: maxX, z: maxZ } };
  }

  buildGrid() {
    this.gridWidth = Math.ceil((this.bounds.max.x - this.bounds.min.x) / this.gridSize);
    this.gridHeight = Math.ceil((this.bounds.max.z - this.bounds.min.z) / this.gridSize);
    this.gridOffsetX = this.bounds.min.x;
    this.gridOffsetZ = this.bounds.min.z;

    this.grid = [];
    for (let x = 0; x < this.gridWidth; x++) {
      this.grid[x] = [];
      for (let z = 0; z < this.gridHeight; z++) {
        const worldX = this.gridToWorldX(x);
        const worldZ = this.gridToWorldZ(z);
        this.grid[x][z] = this.isBlocked(worldX, worldZ) ? 1 : 0;
      }
    }
  }

  isBlocked(x, z) {
    const padding = this.robotRadius + this.gridSize;
    for (const obs of this.obstacles) {
      if (x >= obs.minX - padding && x <= obs.maxX + padding &&
          z >= obs.minZ - padding && z <= obs.maxZ + padding) {
        return true;
      }
    }
    return false;
  }

  worldToGrid(x, z) {
    return {
      x: Math.floor((x - this.gridOffsetX) / this.gridSize),
      z: Math.floor((z - this.gridOffsetZ) / this.gridSize)
    };
  }

  gridToWorldX(gx) {
    return this.gridOffsetX + gx * this.gridSize + this.gridSize / 2;
  }

  gridToWorldZ(gz) {
    return this.gridOffsetZ + gz * this.gridSize + this.gridSize / 2;
  }

  aStarSearch(start, goal) {
    const openSet = new Map();
    const closedSet = new Set();
    const cameFrom = new Map();
    const gScore = new Map();
    const fScore = new Map();

    const key = (p) => `${p.x},${p.z}`;
    const heuristic = (a, b) => Math.abs(a.x - b.x) + Math.abs(a.z - b.z);

    const startKey = key(start);
    openSet.set(startKey, start);
    gScore.set(startKey, 0);
    fScore.set(startKey, heuristic(start, goal));

    const directions = [
      { x: 1, z: 0 }, { x: -1, z: 0 },
      { x: 0, z: 1 }, { x: 0, z: -1 },
      { x: 1, z: 1 }, { x: -1, z: -1 },
      { x: 1, z: -1 }, { x: -1, z: 1 }
    ];

    let iterations = 0;
    const maxIterations = this.gridWidth * this.gridHeight;

    while (openSet.size > 0 && iterations < maxIterations) {
      iterations++;

      let current = null;
      let currentKey = null;
      let minF = Infinity;

      for (const [k, node] of openSet) {
        const f = fScore.get(k) || Infinity;
        if (f < minF) {
          minF = f;
          current = node;
          currentKey = k;
        }
      }

      if (!current) break;

      if (current.x === goal.x && current.z === goal.z) {
        return this.reconstructPath(cameFrom, current);
      }

      openSet.delete(currentKey);
      closedSet.add(currentKey);

      for (const dir of directions) {
        const neighbor = { x: current.x + dir.x, z: current.z + dir.z };
        const neighborKey = key(neighbor);

        if (neighbor.x < 0 || neighbor.x >= this.gridWidth ||
            neighbor.z < 0 || neighbor.z >= this.gridHeight) {
          continue;
        }

        if (this.grid[neighbor.x][neighbor.z] === 1) {
          continue;
        }

        if (closedSet.has(neighborKey)) {
          continue;
        }

        if (Math.abs(dir.x) === 1 && Math.abs(dir.z) === 1) {
          if (this.grid[current.x + dir.x][current.z] === 1 ||
              this.grid[current.x][current.z + dir.z] === 1) {
            continue;
          }
        }

        const moveCost = (Math.abs(dir.x) + Math.abs(dir.z) === 2) ? 1.414 : 1;
        const tentativeG = (gScore.get(currentKey) || 0) + moveCost;

        if (!openSet.has(neighborKey)) {
          openSet.set(neighborKey, neighbor);
        } else if (tentativeG >= (gScore.get(neighborKey) || Infinity)) {
          continue;
        }

        cameFrom.set(neighborKey, current);
        gScore.set(neighborKey, tentativeG);
        fScore.set(neighborKey, tentativeG + heuristic(neighbor, goal));
      }
    }

    return null;
  }

  reconstructPath(cameFrom, current) {
    const path = [current];
    const key = (p) => `${p.x},${p.z}`;

    let currentKey = key(current);
    while (cameFrom.has(currentKey)) {
      current = cameFrom.get(currentKey);
      path.unshift(current);
      currentKey = key(current);
    }

    return path;
  }

  smoothPath(pathGrid) {
    if (pathGrid.length <= 2) return pathGrid;

    const smoothed = [pathGrid[0]];

    for (let i = 1; i < pathGrid.length - 1; i++) {
      const prev = smoothed[smoothed.length - 1];
      const curr = pathGrid[i];
      const next = pathGrid[i + 1];

      const dx1 = curr.x - prev.x;
      const dz1 = curr.z - prev.z;
      const dx2 = next.x - curr.x;
      const dz2 = next.z - curr.z;

      if (dx1 !== dx2 || dz1 !== dz2) {
        smoothed.push(curr);
      }
    }

    smoothed.push(pathGrid[pathGrid.length - 1]);

    return this.visibilitySmooth(smoothed);
  }

  visibilitySmooth(pathGrid) {
    if (pathGrid.length <= 2) return pathGrid;

    const smoothed = [pathGrid[0]];
    let currentIdx = 0;

    while (currentIdx < pathGrid.length - 1) {
      let farthestVisible = currentIdx + 1;

      for (let i = pathGrid.length - 1; i > currentIdx + 1; i--) {
        if (this.hasLineOfSight(pathGrid[currentIdx], pathGrid[i])) {
          farthestVisible = i;
          break;
        }
      }

      smoothed.push(pathGrid[farthestVisible]);
      currentIdx = farthestVisible;
    }

    return smoothed;
  }

  hasLineOfSight(p1, p2) {
    const x1 = this.gridToWorldX(p1.x);
    const z1 = this.gridToWorldZ(p1.z);
    const x2 = this.gridToWorldX(p2.x);
    const z2 = this.gridToWorldZ(p2.z);

    const distance = Math.sqrt((x2 - x1) ** 2 + (z2 - z1) ** 2);
    const steps = Math.ceil(distance / (this.gridSize / 2));

    for (let i = 0; i <= steps; i++) {
      const t = i / steps;
      const x = x1 + (x2 - x1) * t;
      const z = z1 + (z2 - z1) * t;

      if (this.isBlocked(x, z)) {
        return false;
      }
    }

    return true;
  }

  generateDirectPath(start, goal) {
    const path = [{ x: start.x, y: this.groundHeight, z: start.z }];

    const midPoints = 5;
    for (let i = 1; i < midPoints; i++) {
      const t = i / midPoints;
      path.push({
        x: start.x + (goal.x - start.x) * t,
        y: this.groundHeight,
        z: start.z + (goal.z - start.z) * t
      });
    }

    path.push({ x: goal.x, y: this.groundHeight, z: goal.z });
    return path;
  }

  removeRedundantPoints(path) {
    if (path.length <= 2) return path;

    const result = [path[0]];

    for (let i = 1; i < path.length - 1; i++) {
      const prev = result[result.length - 1];
      const curr = path[i];
      const next = path[i + 1];

      const dx1 = curr.x - prev.x;
      const dz1 = curr.z - prev.z;
      const dx2 = next.x - curr.x;
      const dz2 = next.z - curr.z;

      const len1 = Math.sqrt(dx1 * dx1 + dz1 * dz1);
      const len2 = Math.sqrt(dx2 * dx2 + dz2 * dz2);

      if (len1 < 1 || len2 < 1) continue;

      const dot = (dx1 * dx2 + dz1 * dz2) / (len1 * len2);

      if (dot < 0.99) {
        result.push(curr);
      }
    }

    result.push(path[path.length - 1]);
    return result;
  }
}

export default PathPlanner;
